const LIB = "0819f05c4eef4c71ace90d822a990e87";
const log = (m) => console.log(m);

async function findDev(kw) {
  const r = await eda.lib_Device.search(kw, undefined, undefined, undefined, 5, 1);
  return r.length > 0 ? r[0] : null;
}

async function placeComp(dUuid, x, y, des, name, rot) {
  const c = await eda.sch_PrimitiveComponent.create({ uuid: dUuid, libraryUuid: LIB }, x, y, undefined, rot || 0);
  if (c) await eda.sch_PrimitiveComponent.modify(c.primitiveId, { designator: des, name: name || "" });
  return c;
}

const searches = {
  tb6612: "TB6612FNG", mpu6050: "MPU6050",
  cap_100nf: "100nF 0805", cap_220uf: "220uF 63V",
  sw_spdt: "SW-SPDT", dc005: "DC-005",
  h1x2: "Pin Header 1x2", h1x4: "Pin Header 1x4",
  h1x6: "Pin Header 1x6", h1x8: "Pin Header 1x8",
  h1x10: "Pin Header 1x10", h1x12: "Pin Header 1x12",
  h1x15: "Pin Header 1x15", h2x15: "Pin Header 2x15",
  r1k: "1k 0805", r10k: "10k 0805",
  npn: "S8050", buzzer: "Buzzer",
  led_b: "LED 0805 Blue",
};
const devs = {};
for (const [k, kw] of Object.entries(searches)) {
  const d = await findDev(kw);
  devs[k] = d ? d.uuid : null;
  log(k + ": " + (devs[k] ? "OK" : "MISSING"));
}
return devs;
